using UnityEngine;
namespace HonourWar { public enum EHonourWarMonsterSpecies { Poring,Poporing,Drops,Marin,Orc,Goblin,Plant,Beast,Undead,Dragon,Demon,Construct }; public sealed class HonourWarMonster:MonoBehaviour { public string MonsterId,DisplayName; public EHonourWarMonsterSpecies Species; public int Level=1,MaxHP=100,HP=100; public bool IsAlive=>HP>0; public void Initialize(string id,string name,EHonourWarMonsterSpecies species,int level){MonsterId=id;DisplayName=name;Species=species;Level=level;MaxHP=100+level*25;HP=MaxHP;name=name;} public void TakeDamage(int amount){HP=Mathf.Max(0,HP-amount);} public void Restore(){HP=MaxHP;} } }